Given an unsigned integer n. The task is to swap all odd bits with adjacent even bits.Examples: Input: 23Output: 43Explanation: 23 (0010111) should be converted to 43 (0101011).Input: 2Output: 1Explanation: 2 (0010) should be converted to 1 (0001).Try It YourselfTable of Content[Naive Approach] Time O(1) and Space O(1)[Efficient Approach] Time O(1)  and Space O(1)[Naive Approach] Time O(1) and Space O(1)For every even index i in the binary representation of N starting from index 0 swap bits with (i+1)th index.Follow the steps below to implement the idea:Find the bit at i and i+1 index.To swap the bits subtract and add corresponding values.To remove bit at ith bit to i+1. subtract i_bit<<i and add it at i+1 index for that we need to add i_bit<<(i+1).Similarly subtract (i+1)th bit and add it to ith index.
            C++

    #include <iostream>
using namespace std;

unsigned int swapBits(unsigned int n)
{
    for (int i = 0; i < 32; i += 2) {

        // Find i th bit
        int i_bit = (n >> i) & 1;

        // Find i+1 th bit
        int i_1_bit = (n >> (i + 1)) & 1;

        // Remove i_bit
        n = n  - (i_bit << i)
            // Remove i+1 th bit
            - (i_1_bit << (i + 1))
            // Put i_bit at i+1 location
            + (i_bit << (i + 1))
            // Put i+1 bit at i location
            + (i_1_bit << i);
    }
    return n;
}


int main()
{
    unsigned int n = 23;
    cout << swapBits(n);

    return 0;
}


